-- Additive 2.0 research warehouse. Ownership is enforced in application queries;
-- SQLite does not provide PostgreSQL-style row-level security.
CREATE TABLE contract_quotes(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,contract_id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),quoted_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX contract_quotes_owner ON contract_quotes(user_id,contract_id,quoted_at);
CREATE TABLE prediction_snapshots(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,entity_key TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),as_of TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX predictions_owner ON prediction_snapshots(user_id,entity_key,as_of);
CREATE TABLE contract_settlements(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,contract_id TEXT NOT NULL,quote_id TEXT,prediction_id TEXT,data TEXT NOT NULL CHECK(json_valid(data)),settled_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX settlements_owner ON contract_settlements(user_id,contract_id,settled_at);
CREATE TABLE injury_history(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,entity_key TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),source TEXT NOT NULL,observed_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX injuries_owner ON injury_history(user_id,entity_key,observed_at);
CREATE TABLE notification_history(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,data TEXT NOT NULL CHECK(json_valid(data)),created_at TEXT NOT NULL);
CREATE INDEX notification_owner ON notification_history(user_id,created_at);
CREATE TABLE research_records(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,entity_key TEXT NOT NULL DEFAULT '',data TEXT NOT NULL CHECK(json_valid(data)),source TEXT NOT NULL DEFAULT 'user',observed_at TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX research_owner ON research_records(user_id,kind,observed_at);
CREATE TABLE simulation_jobs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL DEFAULT 'matchup',status TEXT NOT NULL DEFAULT 'queued',data TEXT NOT NULL CHECK(json_valid(data)),result TEXT CHECK(result IS NULL OR json_valid(result)),error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX simulation_owner ON simulation_jobs(user_id,status,created_at);
CREATE TABLE paper_positions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,entity_key TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX paper_owner ON paper_positions(user_id,status,created_at);
CREATE TABLE watchlists(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX watchlists_owner ON watchlists(user_id,updated_at);
CREATE TABLE reports(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,kind TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX reports_owner ON reports(user_id,created_at);
CREATE TABLE warehouse_records(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind TEXT NOT NULL,entity_key TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),source TEXT NOT NULL,observed_at TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX warehouse_owner ON warehouse_records(user_id,kind,entity_key,observed_at);
CREATE TABLE conversations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX conversations_owner ON conversations(user_id,updated_at);
CREATE TABLE conversation_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL CHECK(role IN ('user','assistant')),content TEXT NOT NULL,data TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(data)),created_at TEXT NOT NULL);
CREATE INDEX messages_conversation ON conversation_messages(user_id,conversation_id,created_at);
CREATE TABLE preferences(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,key TEXT NOT NULL,value TEXT NOT NULL CHECK(json_valid(value)),updated_at TEXT NOT NULL,PRIMARY KEY(user_id,key));
CREATE TRIGGER contract_quotes_immutable BEFORE UPDATE ON contract_quotes BEGIN SELECT RAISE(ABORT,'Historical snapshots are immutable; append a new record.'); END;
CREATE TRIGGER prediction_snapshots_immutable BEFORE UPDATE ON prediction_snapshots BEGIN SELECT RAISE(ABORT,'Historical snapshots are immutable; append a new record.'); END;
CREATE TRIGGER contract_settlements_immutable BEFORE UPDATE ON contract_settlements BEGIN SELECT RAISE(ABORT,'Historical snapshots are immutable; append a new record.'); END;
CREATE TRIGGER injury_history_immutable BEFORE UPDATE ON injury_history BEGIN SELECT RAISE(ABORT,'Historical snapshots are immutable; append a new record.'); END;
CREATE TRIGGER warehouse_records_immutable BEFORE UPDATE ON warehouse_records BEGIN SELECT RAISE(ABORT,'Historical snapshots are immutable; append a new record.'); END;
PRAGMA user_version = 2;
